await Excel.run(async c => {
  const w = c.workbook;
  const s = w.worksheets.getItem("Sheet1");
  s.getRange("B2:C3").values=[["Item","Sales"],["A",10]];
  const t=s.tables.add("B2:C3",true);
  t.name="Data";
  await c.sync();
  s.getRange("E1").formulas=[["=SUM(Data[Sales])"]];
  s.getRange("B4:C4").values=[["B",20]];
  await c.sync();
  const before=s.getRange("E1"); before.load("values"); await c.sync(); console.log("before_resize="+JSON.stringify(before.values));
  t.resize("B2:C4");
  await c.sync();
  const after=s.getRange("E1"); after.load("values"); await c.sync(); console.log("after_resize="+JSON.stringify(after.values));
  s.getRange("C4").values=[[40]];
  const result=s.getRange("E1");
  result.load("values");
  await c.sync();
  console.log(JSON.stringify(result.values));
});
